const t = phi.text();
const links = phi.query("a", { fields: ["href"], limit: 400 });
const bag = links.items.filter(l => /bag|baggage|luggage/i.test((l.text||"") + " " + (l.href||"")));
return { textHead: t.slice(0, 1500), bagLinks: bag.slice(0, 30), totalLinks: links.total };

const r = phi.goto("https://www.qatarairways.com/en/baggage/allowance.html");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const t = phi.text();
return { title: r.title, url: r.url, text: t.slice(0, 3000) };

const obs = phi.observe({ maxElements: 200 });
const nodes = obs.nodes.map(n => `${n.ref}. ${n.role} "${(n.text||'').slice(0,90)}"`).join("\n");
return { total: obs.total, nodes: nodes.slice(0, 4000) };

const t = phi.text();
const idx = t.toLowerCase().indexOf('checked baggage');
const hits = [];
const re = /[^\n]{0,120}(kg|kilogram|economy)[^\n]{0,120}/gi;
let m; while ((m = re.exec(t)) && hits.length < 40) hits.push(m[0].trim());
return { len: t.length, hits };

const tables = phi.query("table", { limit: 10 });
const links = phi.query("a", { fields: ["href"], limit: 120 });
const rel = links.items.map(i => i.href).filter(h => h && /baggage|allowance|checked/i.test(h));
const btns = phi.query("button, [role=tab], [role=button]", { limit: 60 });
phi.narrate("Looking for the checked baggage section and any weight table");
return { tables: tables.total, relLinks: rel.slice(0, 40), btns: btns.total, btnTexts: btns.items.map(b => (b.text||'').slice(0,60)).filter(Boolean).slice(0,40) };

const obs = phi.observe({ within: "main, body" });
const eco = obs.nodes.filter(n => /Economy/i.test(n.text || "") && /^(button|tab|link)/i.test(n.role || ""));
const tabs = obs.nodes.filter(n => /Class/i.test(n.text || ""));
return { eco: eco.slice(0,6), tabs: tabs.slice(0,10) };

const obs = phi.observe({ maxElements: 300 });
const hits = obs.nodes.filter(n => /class|economy|kg|piece/i.test((n.text || "") + " " + (n.name || "")));
return { total: obs.total, trimmed: obs.nodes.length, hits: hits.map(n => ({ ref: n.ref, role: n.role, text: (n.text || "").slice(0, 80) })).slice(0, 40) };

phi.narrate("Reading the actual baggage tables for weights");
const t = phi.query("table", { limit: 6 });
const out = phi.js(() => {
  const tabs = [...document.querySelectorAll("table")].map(tb => (tb.innerText || "").replace(/\s+/g, " ").slice(0, 600));
  const main = document.querySelector("main") || document.body;
  const txt = (main.innerText || "").replace(/\n{2,}/g, "\n");
  const idx = txt.search(/Economy/i);
  return { tabs, excerpt: txt.slice(Math.max(0, idx - 200), idx + 1800), len: txt.length };
});
return out;

const info = phi.js(() => {
  const all = [...document.querySelectorAll("div,section,table")];
  const cand = all.filter(el => /Economy Lite/i.test(el.innerText || ""));
  // pick the smallest such element (the table itself)
  cand.sort((a, b) => (a.innerText || "").length - (b.innerText || "").length);
  const el = cand[0];
  if (!el) return { found: false };
  el.scrollIntoView({ block: "center" });
  return { found: true, tag: el.tagName, len: (el.innerText || "").length, text: (el.innerText || "").replace(/\s+/g, " ").slice(0, 500) };
});
phi.keep("economy_weights", {
  source: "https://www.qatarairways.com/en/baggage/allowance.html (Economy Class allowance table)",
  economy: {
    carryOn: "1 piece up to 7kg (15lb)",
    "checked_Africa_Americas": "Economy Lite: 1 piece up to 23kg (50lb); Economy Classic / Convenience / Comfort: 2 pieces up to 23kg (50lb) each",
    "checked_all_other_destinations": "Economy Lite 20kg (44lb), Economy Classic 25kg (55lb), Economy Convenience 30kg (66lb), Economy Comfort 35kg (77lb)"
  }
});
phi.look();
return info;

phi.narrate("Scrolling down to the economy table to see the weights on screen");
const r = phi.js(() => {
  const el = [...document.querySelectorAll("*")].find(e => (e.innerText||"").includes("Economy Lite") && e.children.length < 40 && (e.innerText||"").length < 800);
  if (el) el.scrollIntoView({ block: "center" });
  window.scrollBy(0, -80);
  return { ok: !!el, y: window.scrollY, h: document.body.scrollHeight };
});
phi.sleep(1500);
return r;

const t = phi.text();
const tables = phi.query("table", { limit: 20 });
const iframes = phi.query("iframe", { fields: ["src"], limit: 20 });
return { textLen: t.length, textHead: t.slice(0, 1500), tableCount: tables.total, tableTexts: tables.items.map(i => (i.text||"").replace(/\s+/g," ").slice(0,300)), iframes: iframes.items.map(i=>i.src) };

const tables = phi.query("table", { limit: 10 });
const eco = tables.items[1]?.text || "";
const rows = phi.query("table", { limit: 10 }).items[1];
// read economy table rows properly
const ecoRows = phi.js(() => {
  const ts = [...document.querySelectorAll("table")];
  const t = ts.find(t => /Economy Lite/i.test(t.innerText || ""));
  if (!t) return { found: false };
  t.scrollIntoView({ block: "center" });
  const out = [];
  t.querySelectorAll("tr").forEach(tr => {
    out.push([...tr.children].map(td => (td.innerText || "").replace(/\s+/g, " ").trim()));
  });
  return { found: true, rows: out, text: (t.innerText||"").replace(/\s+/g," ") };
});
phi.keep("eco_table", ecoRows);
phi.look();
return ecoRows;

const kept = phi.recall("economy_weights");
const tables = phi.query("table", { limit: 10 });
const eco = tables.items[1] ? tables.items[1].text.replace(/\s+/g, " ").trim() : null;
// scroll the economy table into view using the real element
const scrolled = phi.js(() => {
  const ts = [...document.querySelectorAll("table")];
  const t = ts.find(t => /Economy Lite/i.test(t.innerText || ""));
  if (!t) return { found: false, n: ts.length };
  t.scrollIntoView({ block: "center" });
  return { found: true, y: window.scrollY, rect: t.getBoundingClientRect().top };
});
phi.sleep(1200);
phi.look();
if (eco) phi.keep("eco_weights_final", eco);
return { kept, tableCount: tables.total, ecoFull: eco, scrolled };

const t = phi.query("table", { limit: 10 });
const eco = t.items[1] ? t.items[1].text : null;
const info = phi.js(() => {
  const ts = [...document.querySelectorAll("table")];
  const res = ts.map((el, i) => {
    const txt = (el.textContent || "").replace(/\s+/g, " ");
    return { i, hasEco: /Economy Lite/i.test(txt), len: txt.length, top: el.getBoundingClientRect().top };
  });
  const target = ts.find(el => /Economy Lite/i.test(el.textContent || ""));
  if (target) {
    target.scrollIntoView({ block: "center" });
    return { res, scrolled: true, top: Math.round(target.getBoundingClientRect().top), h: Math.round(target.getBoundingClientRect().height) };
  }
  return { res, scrolled: false };
});
phi.sleep(1000);
if (eco) phi.keep("economy_weights", {
  source: "https://www.qatarairways.com/en/baggage/allowance.html — Economy Class allowance table",
  carryOn: "1 piece up to 7kg (15lb)",
  checked_Africa_or_Americas: "Economy Lite: 1 piece up to 23kg (50lb); Economy Classic/Convenience/Comfort: 2 pieces up to 23kg (50lb) each",
  checked_all_other_destinations: "Economy Lite 20kg (44lb); Economy Classic 25kg (55lb); Economy Convenience 30kg (66lb); Economy Comfort 35kg (77lb)",
  tableTextFull: eco.replace(/\s+/g, " ").trim()
});
return { info, ecoLen: eco ? eco.length : 0, ecoFull: eco ? eco.replace(/\s+/g, " ").trim() : null };

// Look at the whole economy section on screen now, and grab any toggle/dropdown that switches destination rules
const shot = phi.readImage(undefined, "Show any table of baggage allowance by economy fare type. Read out every cell exactly, including weights in kg. Also note if there is a dropdown or toggle for destination region.");
const obs = phi.observe({ maxElements: 200 });
const interesting = obs.nodes.filter(n => /destination|region|piece|weight|Africa|America|show|expand|more/i.test(n.text || "") || n.role === "tab" || n.role === "combobox" || n.role === "button");
return { shot, nodes: interesting.map(n => ({ ref: n.ref, role: n.role, text: (n.text||"").slice(0,90) })), total: obs.total };
